const d = $json.documents;
const verified = d.filter(x => x.verified).length;
const ocrConfidence = d.length ? Math.round(60 + 40 * (verified / d.length)) : 40;
return [{ json: { ...$json, ocrConfidence, documentsVerified: d.length > 0 && verified === d.length } }];

const disputed = $json.property.status === 'disputed';
const fraudScore = disputed ? 86 : 12;
const fraudBand = fraudScore >= 80 ? 'Critical' : fraudScore >= 50 ? 'Elevated' : fraudScore >= 25 ? 'Watch' : 'Clear';
return [{ json: { ...$json, fraudScore, fraudBand } }];

const v = $json.property.boundaryVertices ?? 0;
const boundaryScore = v >= 3 ? 94 : 55;
return [{ json: { ...$json, boundaryScore, boundaryVerified: v >= 3 && boundaryScore >= 70 } }];

const p = $json.property;
const verifiedDocs = $json.documents.filter(d => d.verified).length;
const documentScore = $json.ocrConfidence;
const registryEvidence = p.status === 'verified' ? 95 : p.status === 'disputed' ? 30 : 60;
const governmentScore = Math.round((documentScore + registryEvidence) / 2);
const governmentCleared = p.status === 'verified' && $json.documentsVerified && governmentScore >= 70;
return [{ json: { ...$json, documentScore, governmentScore, governmentCleared } }];

const p = $json.property;
const communityScore = p.status === 'disputed' ? 35 : p.status === 'verified' ? 92 : 62;
const communityAttestations = Math.max(0, Math.round((communityScore - 50) / 6));
const communityCleared = p.status !== 'disputed' && communityScore >= 65;
return [{ json: { ...$json, communityScore, communityAttestations, communityCleared } }];

const disputed = $json.property.status === 'disputed';
const riskScore = disputed ? 62 : 18;
return [{ json: { ...$json, riskScore, registryCrossCheck: !disputed && $json.property.status !== 'pending' } }];

const w = { docs: 0.22, boundary: 0.14, government: 0.16, community: 0.13, risk: 0.18, fraud: 0.17 };
const confidenceScore = Math.round(
  $json.ocrConfidence * w.docs +
  $json.boundaryScore * w.boundary +
  $json.governmentScore * w.government +
  $json.communityScore * w.community +
  (100 - $json.riskScore) * w.risk +
  (100 - $json.fraudScore) * w.fraud
);
return [{ json: { ...$json, confidenceScore, confidence: confidenceScore } }];

const s = $json;
const reasons = [];
if (s.fraudScore >= 25) reasons.push('fraud status ' + s.fraudBand + ' (' + s.fraudScore + ')');
if (s.confidenceScore < 78) reasons.push('confidence ' + s.confidenceScore + ' below the 78 auto-approve threshold');
if (!s.boundaryVerified) reasons.push('boundary polygon not hardened by field capture');
if (!s.documentsVerified) reasons.push('one or more documents unverified');
if (!s.governmentCleared) reasons.push('prototype government registry validation did not clear');
if (!s.communityCleared) reasons.push('prototype community evidence contains an objection or is incomplete');
if (s.riskScore >= 45) reasons.push('risk score ' + s.riskScore + ' exceeds the acceptable band');
return [{ json: { ...s, workflowId: 'WF-N8N-' + s.passportId.replace(/[^A-Z0-9]/gi,'') + '-' + Date.now().toString(36).toUpperCase(), documentScore: s.ocrConfidence, fraudStatus: s.fraudBand, confidence: s.confidenceScore, decision: 'HUMAN_REVIEW_REQUIRED', status: 'manual_review', passportStatus: 'held', decisionReason: 'Human review required because the property contains conflicting ownership/boundary evidence: ' + reasons.join('; ') + '.', reviewReasons: reasons, completedAt: new Date().toISOString(), steps: [ { name: 'Property submitted', status: 'completed' }, { name: 'Document / OCR check', status: s.documentsVerified ? 'completed' : 'attention', score: s.ocrConfidence }, { name: 'Fraud analysis', status: s.fraudScore >= 25 ? 'attention' : 'completed', score: s.fraudScore }, { name: 'Boundary verification', status: s.boundaryVerified ? 'completed' : 'attention', score: s.boundaryScore }, { name: 'Government validation', status: s.governmentCleared ? 'completed' : 'attention', score: s.governmentScore }, { name: 'Community verification', status: s.communityCleared ? 'completed' : 'attention', score: s.communityScore }, { name: 'Risk analysis', status: s.riskScore >= 45 ? 'attention' : 'completed', score: s.riskScore }, { name: 'Confidence engine', status: 'completed', score: s.confidenceScore }, { name: 'Automated decision', status: 'attention', detail: 'Human review required' }, { name: 'Passport readiness', status: 'attention', detail: 'Held pending human sign-off' } ] } }];
